insert into pb_ai.kb_chunks (version, ord, lib, chunk)
select 'b3e91f6c47d2', m.mx + row_number() over (order by t.i), t.e->>'lib', t.e->'chunk'
  from jsonb_array_elements($kb$[{"lib": "field", "chunk": {"id": "dig-co-locatable-1", "state": "CO", "tier": "core", "title": "Colorado: new underground lines must be electronically locatable (tracer wire on PVC)", "topic": "Locatable pipe: tracer wire and locating rules", "text": "Colorado law requires all new underground facilities installed on or after August 8, 2018 to be electronically locatable, including laterals up to the building they serve (C.R.S. 9-1.5-103(10)). The Colorado Underground Damage Prevention Safety Commission says the install method does not change this (pipe bursting counts), planned replacement or rehab is treated as new work, and routine repairs are not included. For PVC and other pipe a locator cannot find, a tracer wire or another locating method is part of the design and install; the Commission does not pick the method. If a tracer wire is cut, repair it or otherwise keep the line locatable. Your project spec sets the wire type, splices and test stations.", "source": "C.R.S. 9-1.5-103(10), as quoted in Colorado UDPSC Best Practice \"Electronically Locatable\" (approved 2019-11-14)", "url": "https://ops.colorado.gov/sites/ops/files/BestPracticeElectronicallyLocatable.pdf", "checked": "2026-11-20", "edition": "Best Practice approved November 14, 2019", "effective": "2018-08-08", "confidence": "medium", "kind": "summary", "license": "gov-state", "note": "Read through the Commission page, not the statute text itself; re-read 9-1.5-103 on leg.colorado.gov to make it high."}},
{"lib": "field", "chunk": {"id": "dig-in-locatable-1", "state": "IN", "tier": "core", "title": "Indiana: new or replacement underground lines must be detectable (locating wire on nonmetallic pipe)", "topic": "Locatable pipe: tracer wire and locating rules", "text": "Indiana law (IC 8-1-26-18.5) covers any new or replacement underground facility installed after June 30, 2020, in public right-of-way or on private property. The operator (whoever installs it or has it installed) must make sure it can be detected from above ground. If the material cannot be found with standard locating equipment, as with PVC or HDPE, the facility must be encased in conductive material or equipped with an electrically conducting wire or other means of locating it underground. In practice that means tracer wire on plastic water and sewer pipe unless the plans call for another method. The section does not list exceptions such as sewer laterals in the text read; check with the owner or engineer.", "source": "Indiana Code 8-1-26-18.5 (read at FindLaw; verify the current text at iga.in.gov)", "url": "https://codes.findlaw.com/in/title-8-utilities-and-transportation/in-code-sect-8-1-26-18-5/", "checked": "2026-11-20", "effective": "2020-07-01", "confidence": "medium", "kind": "summary", "license": "gov-state", "note": "FindLaw copy; re-read on iga.in.gov to make it high."}},
{"lib": "field", "chunk": {"id": "dig-wv-locatable-1", "state": "WV", "tier": "core", "title": "West Virginia: underground lines installed since July 1, 2018 must be locatable", "topic": "Locatable pipe: tracer wire and locating rules", "text": "West Virginia law (W. Va. Code 24C-1-11) says underground facilities owned by an operator and installed on or after July 1, 2018 must be installed so they are locatable using a generally accepted locating method. The law does not name a method; for PVC, HDPE and other nonmetallic pipe that usually means tracer wire or another method the owner accepts. The project spec and the utility owner set the wire, splices and test points.", "source": "W. Va. Code 24C-1-11 (West Virginia Legislature)", "url": "https://code.wvlegislature.gov/pdf/24C-1-11/", "checked": "2026-11-20", "effective": "2018-07-01", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"lib": "field", "chunk": {"id": "dig-ne-locatable-1", "state": "NE", "tier": "core", "title": "Nebraska: plastic and nonmetallic lines installed since 2021 must be locatable (mapping or tracer wire)", "topic": "Locatable pipe: tracer wire and locating rules", "text": "Nebraska law (Neb. Rev. Stat. 76-2320.02) says plastic or nonmetallic underground facilities installed on or after January 1, 2021 must be installed so the operator can locate them under the One-Call Notification System Act, either by mapping or by tracer wire. The owner picks which; ask before you lay plastic pipe whether tracer wire is required. This was read from a 2020 compilation, so the current wording is not confirmed; check it on the Nebraska Legislature site.", "source": "Neb. Rev. Stat. 76-2320.02 (2020 compilation read at Justia; current text at nebraskalegislature.gov not read)", "url": "https://law.justia.com/codes/nebraska/2020/chapter-76/statute-76-2320-02/index.html", "checked": "2026-11-20", "effective": "2021-01-01", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "yes", "note": "Current text not confirmed (Justia says a newer version exists)."}},
{"lib": "field", "chunk": {"id": "dig-mn-locatable-1", "state": "MN", "tier": "core", "title": "Minnesota: nonconductive lines in public right-of-way need a locating wire (Rule 7560.0150)", "topic": "Locatable pipe: tracer wire and locating rules", "text": "Minnesota Rule 7560.0150, subpart 2: for each nonconductive underground facility installed in a public right-of-way after December 31, 2005, the operator must install a locating wire (tracer wire) or an equally effective means of marking where it is. Minor repairs, meaning repairs to or partial replacement of existing service laterals for routine upkeep, are not covered. Subpart 1 also has operators keep records (map, drawing or GIS) of facilities they install in public right-of-way. This is the 2014 version of the rule as read; the current version is not confirmed, so check it at revisor.mn.gov.", "source": "Minnesota Rules 7560.0150, subparts 1 and 2 (version of 2014-01-18 at revisor.mn.gov)", "url": "https://www.revisor.mn.gov/rules/7560.0150/version/2014-01-18T09:37:50-06:00", "checked": "2026-11-20", "edition": "Rule version 2014-01-18", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "yes", "note": "Read the 2014 version page; current version not opened."}},
{"lib": "field", "chunk": {"id": "fed-phmsa-tracer-1", "state": "US", "tier": "core", "title": "Gas lines: plastic pipe must have a tracer wire or other way to locate it (49 CFR 192.321(e))", "topic": "Locatable pipe: tracer wire and locating rules", "text": "Federal gas pipeline rule 49 CFR 192.321(e): \"Plastic pipe that is not encased must have an electrically conducting wire or other means of locating the pipe while it is underground.\" Tracer wire may not be wrapped around the pipe, contact with the pipe should be kept small, and the wire must resist corrosion (coated copper or another means). This rule is for gas transmission lines and mains. Water and sewer tracer wire comes from state law in some states and from the project spec everywhere else.", "source": "49 CFR 192.321(e), Installation of plastic pipe (eCFR / LII)", "url": "https://www.law.cornell.edu/cfr/text/49/192.321", "checked": "2026-11-20", "edition": "49 CFR as current on 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us"}}]$kb$::jsonb) with ordinality t(e, i),
